import {recipe,svg,random,contrast,rgbToHex,animationDuration} from './core.mjs';
export async function drawSVG(canvas,source){const url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height)}finally{URL.revokeObjectURL(url)}}
export function canvasBlob(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('The browser could not export this image.')),'image/png'))}
export async function png(source,width=1920,height=Math.round(width*9/16)){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;await drawSVG(canvas,source);return canvasBlob(canvas)}
export function gradientTool({change,status}){
  const $=id=>document.getElementById(id),canvas=$('gradient-canvas');let state=recipe(),generation=0,drag=-1;
  const pointControls=()=>{
    const list=$('gradient-point-controls');list.replaceChildren();
    (state.type==='radial'?state.points.slice(0,1):state.points).forEach((p,i)=>{const row=document.createElement('div');row.className='studio-point';const title=document.createElement('span');title.textContent=String(i+1);row.append(title);for(const axis of ['x','y']){const label=document.createElement('label');label.textContent=axis.toUpperCase();const input=document.createElement('input');input.type='range';input.min=0;input.max=100;input.value=Math.round(p[axis]*100);input.setAttribute('aria-label',`${state.type==='radial'?'Radial centre':'Mesh point '+(i+1)} ${axis.toUpperCase()} position`);input.oninput=()=>{state.points[i][axis]=Number(input.value)/100;draw();change()};label.append(input);row.append(label)}list.append(row)});
    list.hidden=!['mesh','radial'].includes(state.type);$('gradient-mesh-actions').hidden=state.type!=='mesh';$('gradient-add-point').disabled=state.points.length>=9;$('gradient-remove-point').disabled=state.points.length<=3;
  };
  function colours(){const box=$('gradient-colours');box.replaceChildren();state.colors.forEach((c,i)=>{const row=document.createElement('div');row.className='studio-colour-row';const color=document.createElement('input');color.type='color';color.value=c;color.setAttribute('aria-label',`Colour ${i+1}`);color.oninput=()=>{state.colors[i]=color.value;draw();change()};const supportsStops=['linear','radial','conic'].includes(state.type),stop=document.createElement('input');stop.type='number';stop.min=0;stop.max=100;stop.step=.1;stop.value=Number(state.stops[i].toFixed(1));stop.setAttribute('aria-label',`Colour ${i+1} stop percentage`);stop.onchange=()=>{state.stops[i]=Math.max(0,Math.min(100,Number(stop.value)||0));state=recipe(state);sync()};const remove=document.createElement('button');remove.type='button';remove.className='studio-small-button';remove.textContent='−';remove.setAttribute('aria-label',`Remove colour ${i+1}`);remove.disabled=state.colors.length<=2;remove.onclick=()=>{state.colors.splice(i,1);state.stops.splice(i,1);sync()};const name=document.createElement('span');name.className='studio-note';name.textContent='Colour '+(i+1);row.append(color,supportsStops?stop:name,remove);box.append(row)});$('gradient-add-colour').disabled=state.colors.length>=6;$('gradient-colours-label').textContent=['linear','radial','conic'].includes(state.type)?'Colours and stop positions':'Colours';}
  function checkContrast(){let white=21,black=21;const ctx=canvas.getContext('2d');for(let y=.35;y<.7;y+=.07)for(let x=.08;x<.55;x+=.08){const c=rgbToHex([...ctx.getImageData(Math.round(x*canvas.width),Math.round(y*canvas.height),1,1).data].slice(0,3).map(n=>n/255));white=Math.min(white,contrast(c,'#ffffff'));black=Math.min(black,contrast(c,'#101113'))}const selected=$('gradient-copy-tone').value,tone=selected==='auto'?(black>=white?'dark':'light'):selected;$('gradient-preview-copy').dataset.tone=tone;const ratio=tone==='dark'?black:white;$('gradient-contrast').textContent=`Sample area: ${ratio.toFixed(1)}:1${ratio<4.5?' · try another text colour':''}`}
  async function draw(){const n=++generation;const temp=document.createElement('canvas');temp.width=canvas.width;temp.height=canvas.height;try{await drawSVG(temp,svg(state,960,540));if(n!==generation)return;canvas.getContext('2d').drawImage(temp,0,0);checkContrast();$('gradient-stage').classList.toggle('is-animated',state.animate);const points=$('gradient-points');points.replaceChildren();if(state.type==='mesh')state.points.forEach((p,i)=>{const handle=document.createElement('div');handle.className='studio-point-handle';handle.style.left=p.x*100+'%';handle.style.top=p.y*100+'%';handle.style.background=state.colors[i%state.colors.length];const label=document.createElement('span');label.textContent=String(i+1);handle.append(label);points.append(handle)})}catch(e){status(e.message,true)}}
  function sync(){state=recipe(state);$('gradient-type').value=state.type;$('gradient-angle').closest('label').hidden=!['linear','conic'].includes(state.type);$('gradient-angle').value=state.angle;$('gradient-angle-value').value=state.angle+'°';$('gradient-grain').value=state.grain;$('gradient-grain-value').value=state.grain+'%';$('gradient-animate').checked=state.animate;colours();pointControls();draw();change()}
  $('gradient-type').onchange=e=>{state.type=e.target.value;sync()};
  for(const [id,key] of [['gradient-angle','angle'],['gradient-grain','grain']])$(id).oninput=e=>{state[key]=Number(e.target.value);$(id+'-value').value=state[key]+(key==='angle'?'°':'%');draw();change()};
  function animation(){const stage=$('gradient-stage');stage.style.setProperty('--studio-animation-duration',animationDuration(state)+'s');$('gradient-speed').value=state.speed;$('gradient-speed-value').value=state.speed+'×';$('gradient-speed').disabled=!state.animate;stage.classList.toggle('is-animated',state.animate)}
  $('gradient-animate').onchange=e=>{state.animate=e.target.checked;animation();change()};
  $('gradient-speed').oninput=e=>{state.speed=Number(e.target.value);animation();change()};
  $('gradient-add-colour').onclick=()=>{if(state.colors.length>=6)return;state.colors.push('#d6fb79');state.stops=state.colors.map((_,i)=>Math.round(i*100/(state.colors.length-1)));sync()};
  $('gradient-add-point').onclick=()=>{if(state.points.length>=9)return;state.points.push({x:.5,y:.5});sync()};$('gradient-remove-point').onclick=()=>{if(state.points.length<=3)return;state.points.pop();sync()};
  $('gradient-shuffle').onclick=()=>{state.seed=Math.floor(Math.random()*2147483647);const rnd=random(state.seed);state.points=state.points.map(()=>({x:rnd(),y:rnd()}));state.angle=Math.floor(rnd()*360);sync()};
  $('gradient-show-copy').onchange=e=>$('gradient-preview-copy').hidden=!e.target.checked;$('gradient-copy-tone').onchange=checkContrast;
  function move(event){const rect=canvas.getBoundingClientRect(),x=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height));state.points[drag]={x,y};draw();change()}
  canvas.onpointerdown=e=>{if(state.type!=='mesh')return;const rect=canvas.getBoundingClientRect();let distance=40;state.points.forEach((p,i)=>{const d=Math.hypot(rect.left+p.x*rect.width-e.clientX,rect.top+p.y*rect.height-e.clientY);if(d<distance){drag=i;distance=d}});if(drag>=0){canvas.setPointerCapture(e.pointerId);move(e)}};canvas.onpointermove=e=>{if(drag>=0)move(e)};const end=()=>{if(drag>=0){drag=-1;pointControls()}};canvas.onpointerup=end;canvas.onpointercancel=end;
  sync();animation();return {get:()=>recipe(state),set:v=>{state=recipe(v);sync();animation()},width:()=>Number($('gradient-size').value)};
}
